func rebuildSingBoxConfig(dir string,st State)error{port,secret:=readClashAPIConfig();used:=map[string]int{};outbounds:=[]interface{}{map[string]interface{}{"type":"direct","tag":"DIRECT"}};refTags:=map[string]string{};var testTags []string;subTags:=map[string][]string{};for _,item:=range allNodes(st){tag:=uniqueTag(item.Group+" · "+item.Node.Name,used);o,err:=singBoxOutboundFromNode(item.Node,tag);if err!=nil{continue};outbounds=append(outbounds,o);refTags[item.Ref]=tag;testTags=append(testTags,tag);if strings.HasPrefix(item.Ref,"sub:"){parts:=strings.SplitN(strings.TrimPrefix(item.Ref,"sub:"),":",2);if len(parts)==2{subTags[parts[0]]=append(subTags[parts[0]],tag)}}};var chainTags []string;for _,ch:=range st.Chains{if !ch.Enabled||len(ch.Hops)<2{continue};prev:="";ok:=true;for i,ref:=range ch.Hops{n,exists:=resolveNodeRef(st,ref);if !exists{ok=false;break};tag:=uniqueTag(fmt.Sprintf("CHAIN · %s · %d",ch.Name,i+1),used);o,err:=singBoxOutboundFromNode(n,tag);if err!=nil{ok=false;break};if prev!=""{o["detour"]=prev};outbounds=append(outbounds,o);prev=tag};if ok&&prev!=""{refTags[chainRef(ch.ID)]=prev;chainTags=append(chainTags,prev);testTags=append(testTags,prev)}};selectorItems:=[]string{"AUTO"};for _,sub:=range st.Subscriptions{items:=subTags[sub.ID];if len(items)==0{continue};g:=uniqueTag("SUB · "+sub.Name,used);outbounds=append(outbounds,map[string]interface{}{"type":"selector","tag":g,"outbounds":items,"interrupt_exist_connections":true});selectorItems=append(selectorItems,g)};for _,n:=range st.Servers{if tag:=refTags[nodeRefLocal(n.ID)];tag!=""{selectorItems=append(selectorItems,tag)}};selectorItems=append(selectorItems,chainTags...);selectorItems=append(selectorItems,"DIRECT");if len(testTags)==0{testTags=[]string{"DIRECT"}};outbounds=append(outbounds,map[string]interface{}{"type":"urltest","tag":"AUTO","outbounds":testTags,"url":"https://www.gstatic.com/generate_204","interval":"5m","tolerance":50});proxy:=map[string]interface{}{"type":"selector","tag":"PROXY","outbounds":selectorItems,"interrupt_exist_connections":true};if st.SelectedNode!=""&&st.SelectedNode!="auto"{if t:=refTags[st.SelectedNode];t!=""{proxy["default"]=t}}else{proxy["default"]="AUTO"};outbounds=append(outbounds,proxy);rules,ruleSets:=singBoxRouteRules(st);final:="PROXY";if st.Mode=="direct"{final="DIRECT"};cfg:=map[string]interface{}{"log":map[string]interface{}{"level":"info","timestamp":true},"dns":map[string]interface{}{"servers":[]interface{}{map[string]interface{}{"type":"udp","tag":"dns-direct","server":"1.1.1.1"}},"final":"dns-direct","strategy":"prefer_ipv4"},"inbounds":[]interface{}{map[string]interface{}{"type":"mixed","tag":"mixed-in","listen":"::","listen_port":7080},map[string]interface{}{"type":"tproxy","tag":"tproxy-in","listen":"::","listen_port":1536}},"outbounds":outbounds,"route":map[string]interface{}{"rules":rules,"rule_set":ruleSets,"find_process":true,"final":final},"experimental":map[string]interface{}{"cache_file":map[string]interface{}{"enabled":true,"path":filepath.Join(dir,"sing-box-cache.db")},"clash_api":map[string]interface{}{"external_controller":"127.0.0.1:"+port,"secret":secret,"default_mode":"Rule"}}};b,_:=json.MarshalIndent(cfg,"","  ");target:=singBoxConfigPath();old,_:=os.ReadFile(target);if err:=atomicWrite(target,append(b,'\n'),0644);err!=nil{return err};if err:=validateJSONCoreConfig("sing-box",target);err!=nil{if len(old)>0{_=atomicWrite(target,old,0644)};return fmt.Errorf("sing-box config validation failed: %w",err)};return nil}

func singBoxRouteRules(st State)([]interface{},[]interface{}){rules:=[]interface{}{map[string]interface{}{"action":"sniff"},map[string]interface{}{"type":"logical","mode":"or","rules":[]interface{}{map[string]interface{}{"port":53},map[string]interface{}{"protocol":"dns"}},"action":"hijack-dns"}};sets:=[]interface{}{};if st.Mode!="routing"{return rules,sets};idx:=findRouting(st.Routings,st.ActiveRouting);if idx<0{rules=append(rules,map[string]interface{}{"ip_is_private":true,"action":"route","outbound":"DIRECT"});return rules,sets};var r map[string]interface{};if json.Unmarshal(st.Routings[idx].Raw,&r)!=nil{return rules,sets};setSeen:=map[string]bool{};appendClass:=func(siteKey,ipKey,outbound string,reject bool){for _,raw:=range stringSlice(firstInterface(r,siteKey,lowerFirst(siteKey))){x:=strings.TrimSpace(raw);if x==""{continue};lx:=strings.ToLower(x);if strings.HasPrefix(lx,"geosite:"){name:=strings.TrimSpace(x[len("geosite:"):]);tag:="geosite-"+safeID(name);if !setSeen[tag]{setSeen[tag]=true;sets=append(sets,map[string]interface{}{"type":"remote","tag":tag,"format":"binary","url":"https://raw.githubusercontent.com/SagerNet/sing-geosite/rule-set/geosite-"+url.PathEscape(name)+".srs","download_detour":"PROXY","update_interval":"24h"})};rule:=map[string]interface{}{"rule_set":[]string{tag}};if reject{rule["action"]="reject"}else{rule["action"]="route";rule["outbound"]=outbound};rules=append(rules,rule);continue};val:=strings.TrimPrefix(strings.TrimPrefix(x,"+."),".");rule:=map[string]interface{}{"domain_suffix":[]string{val}};if reject{rule["action"]="reject"}else{rule["action"]="route";rule["outbound"]=outbound};rules=append(rules,rule)};for _,raw:=range stringSlice(firstInterface(r,ipKey,lowerFirst(ipKey))){x:=strings.TrimSpace(raw);if x==""{continue};lx:=strings.ToLower(x);if strings.HasPrefix(lx,"geoip:"){name:=strings.TrimSpace(x[len("geoip:"):]);tag:="geoip-"+safeID(name);if !setSeen[tag]{setSeen[tag]=true;sets=append(sets,map[string]interface{}{"type":"remote","tag":tag,"format":"binary","url":"https://raw.githubusercontent.com/MetaCubeX/meta-rules-dat/sing/geo/geoip/"+url.PathEscape(name)+".srs","download_detour":"PROXY","update_interval":"10d"})};rule:=map[string]interface{}{"rule_set":[]string{tag}};if reject{rule["action"]="reject"}else{rule["action"]="route";rule["outbound"]=outbound};rules=append(rules,rule);continue};cidr:=x;if !strings.Contains(cidr,"/"){if strings.Contains(cidr,":"){cidr+="/128"}else{cidr+="/32"}};rule:=map[string]interface{}{"ip_cidr":[]string{cidr}};if reject{rule["action"]="reject"}else{rule["action"]="route";rule["outbound"]=outbound};rules=append(rules,rule)}};order:=strings.ToLower(firstString(r,"RouteOrder","routeOrder"));if order==""{order="block-proxy-direct"};seen:=map[string]bool{};for _,piece:=range strings.Split(order,"-"){switch strings.TrimSpace(piece){case "block":appendClass("BlockSites","BlockIp","",true);seen["block"]=true;case "proxy":appendClass("ProxySites","ProxyIp","PROXY",false);seen["proxy"]=true;case "direct":appendClass("DirectSites","DirectIp","DIRECT",false);seen["direct"]=true}};if !seen["block"]{appendClass("BlockSites","BlockIp","",true)};if !seen["proxy"]{appendClass("ProxySites","ProxyIp","PROXY",false)};if !seen["direct"]{appendClass("DirectSites","DirectIp","DIRECT",false)};return rules,sets}

func xrayOutboundFromNode(n ServerEntry,tag string)(map[string]interface{},error){if n.RawKind=="xray"&&n.Raw!=nil{m:=cloneMap(n.Raw);m["tag"]=tag;return m,nil};if n.RawKind=="sing-box"{return nil,errors.New("sing-box-only JSON node cannot be used by Xray/V2Ray")};p:=n.Proxy;if p==nil{return nil,errors.New("empty node")};typ:=strings.ToLower(stringValue(p["type"]));server:=stringValue(p["server"]);port:=intValue(p["port"]);m:=map[string]interface{}{"tag":tag};switch typ{case "vless":user:=map[string]interface{}{"id":stringValue(p["uuid"]),"encryption":"none"};if flow:=stringValue(p["flow"]);flow!=""{user["flow"]=flow};m["protocol"]="vless";m["settings"]=map[string]interface{}{"vnext":[]interface{}{map[string]interface{}{"address":server,"port":port,"users":[]interface{}{user}}}};m["streamSettings"]=xrayStreamSettings(p,true);case "vmess":user:=map[string]interface{}{"id":stringValue(p["uuid"]),"security":"auto"};if aid:=intValue(p["alterId"]);aid!=0{user["alterId"]=aid};m["protocol"]="vmess";m["settings"]=map[string]interface{}{"vnext":[]interface{}{map[string]interface{}{"address":server,"port":port,"users":[]interface{}{user}}}};m["streamSettings"]=xrayStreamSettings(p,false);case "trojan":m["protocol"]="trojan";m["settings"]=map[string]interface{}{"servers":[]interface{}{map[string]interface{}{"address":server,"port":port,"password":stringValue(p["password"])}}};m["streamSettings"]=xrayStreamSettings(p,true);case "ss":m["protocol"]="shadowsocks";m["settings"]=map[string]interface{}{"servers":[]interface{}{map[string]interface{}{"address":server,"port":port,"method":stringValue(p["cipher"]),"password":stringValue(p["password"])}}};case "socks5","socks":srv:=map[string]interface{}{"address":server,"port":port};if u:=stringValue(p["username"]);u!=""{srv["users"]=[]interface{}{map[string]interface{}{"user":u,"pass":stringValue(p["password"])}}};m["protocol"]="socks";m["settings"]=map[string]interface{}{"servers":[]interface{}{srv}};case "hysteria2":return nil,errors.New("Hysteria2 is not supported by Xray/V2Ray core");default:return nil,fmt.Errorf("protocol %s is not supported by Xray generator",typ)};return m,nil}
func xrayStreamSettings(p map[string]interface{},forceTLS bool)map[string]interface{}{s:=map[string]interface{}{};netw:=strings.ToLower(stringValue(p["network"]));if netw!=""{if netw=="http"{netw="xhttp"};s["network"]=netw};if forceTLS||boolish(p["tls"],false)||p["reality-opts"]!=nil{if ro,ok:=p["reality-opts"].(map[string]interface{});ok&&len(ro)>0{s["security"]="reality";rs:=map[string]interface{}{};if v:=firstNonEmpty(stringValue(p["servername"]),stringValue(p["sni"]));v!=""{rs["serverName"]=v};if v:=stringValue(ro["public-key"]);v!=""{rs["fingerprint"]=firstNonEmpty(stringValue(p["client-fingerprint"]),"chrome");rs["publicKey"]=v};if v:=stringValue(ro["short-id"]);v!=""{rs["shortId"]=v};s["realitySettings"]=rs}else{s["security"]="tls";ts:=map[string]interface{}{};if v:=firstNonEmpty(stringValue(p["servername"]),stringValue(p["sni"]));v!=""{ts["serverName"]=v};if boolish(p["skip-cert-verify"],false){ts["allowInsecure"]=true};if v:=stringValue(p["client-fingerprint"]);v!=""{ts["fingerprint"]=v};s["tlsSettings"]=ts}};if netw=="ws"{if o,ok:=p["ws-opts"].(map[string]interface{});ok{ws:=map[string]interface{}{};if v:=o["path"];v!=nil{ws["path"]=v};if h,ok:=o["headers"].(map[string]interface{});ok{ws["headers"]=h};s["wsSettings"]=ws}};if netw=="grpc"{if o,ok:=p["grpc-opts"].(map[string]interface{});ok{s["grpcSettings"]=map[string]interface{}{"serviceName":stringValue(o["grpc-service-name"])}}};return s}
